bel":"Netral","value":"3"},{"label":"Sesuai","value":"4"},{"label":"Sangat sesuai","value":"5"}],"scoring_meta":{"source":"testbank-2026-10","instrument":"IPIP-BFM-50","factor":"ES","keyed":"-","dimension":"N","reversed":false}},{"item_order":50,"section":"bigfive","question_text":"Memiliki banyak ide","options":[{"label":"Sangat tidak sesuai","value":"1"},{"label":"Tidak sesuai","value":"2"},{"label":"Netral","value":"3"},{"label":"Sesuai","value":"4"},{"label":"Sangat sesuai","value":"5"}],"scoring_meta":{"source":"testbank-2026-10","instrument":"IPIP-BFM-50","factor":"O","keyed":"+","dimension":"O","reversed":false}}]'::jsonb)
    AS s(item_order int, section text, question_text text, options jsonb, scoring_meta jsonb)
),
upd AS (
  UPDATE test_items t
  SET section = src.section, question_text = src.question_text, options = src.options,
      scoring_meta = src.scoring_meta, test_id = 6, updated_at = now()
  FROM src
  WHERE t.test_code = 'bigfive' AND t.item_order = src.item_order
  RETURNING t.item_order
),
ins AS (
  INSERT INTO test_items (test_code, test_id, section, item_order, question_text, options, scoring_meta, created_at, updated_at)
  SELECT 'bigfive', 6, src.section, src.item_order, src.question_text, src.options, src.scoring_meta, now(), now()
  FROM src
  WHERE NOT EXISTS (SELECT 1 FROM test_items t WHERE t.test_code = 'bigfive' AND t.item_order = src.item_order)
  RETURNING item_order
),
del AS (
  DELETE FROM test_items t
  WHERE t.test_code = 'bigfive' AND t.item_order > 50
    AND NOT EXISTS (SELECT 1 FROM test_responses r WHERE r.item_id = t.id)
  RETURNING 1
)
SELECT (SELECT count(*) FROM upd) AS updated, (SELECT count(*) FROM ins) AS inserted, (SELECT count(*) FROM del) AS deleted;

UPDATE scoring_configs SET formula_type = 'ipip_bfm_50', config_data = '{"seed":"testbank-2026-10","instrument":"IPIP-BFM-50","translation":"Hanif Akhtar (Univ. Muhammadiyah Malang) — https://ipip.ori.org/IndonesianBFM.htm ; versi 25 item: https://ipip.ori.org/Indonesian25BFM.htm (Akhtar & Azwar 2018, J. Innovation in Psychology, Education and Didactics 22:167-174)","license":"Public domain (IPIP): bebas dipakai, diubah, diterjemahkan, termasuk komersial.","keys":{"E":{"plus":[1,11,21,31,41],"minus":[6,16,26,36,46]},"A":{"plus":[7,17,27,37,42,47],"minus":[2,12,22,32]},"C":{"plus":[3,13,23,33,43,48],"minus":[8,18,28,38]},"ES":{"plus":[9,19],"minus":[4,14,24,29,34,39,44,49]},"O":{"plus":[5,15,25,35,40,45,50],"minus":[10,20,30]}},"scoring":"Item + : 1..5 apa adanya; item − : 6 − respon. Skor faktor = jumlah 10 item (rentang 10–50). Faktor: 1 Extraversion, 2 Agreeableness, 3 Conscientiousness, 4 Emotional Stability (kebalikan Neuroticism; N = 60 − ES bila perlu), 5 Intellect/Imagination (Openness).","scoring_source":"https://ipip.ori.org/newScoringInstructions.htm","norms":null,"norms_note":"Tidak ada norma resmi IPIP; IPIP menyarankan norma lokal. Belum ditemukan tabel norma Indonesia → pakai skor mentah/rerata atau bangun norma lokal (persentil) dari data sendiri."}'::jsonb WHERE test_id = 6;

UPDATE master_tests SET total_questions = 50, name = 'Big Five Personality (IPIP-BFM-50)', instructions = 'Deskripsikan diri Anda sebagaimana Anda umumnya saat ini, bukan seperti yang Anda inginkan di masa depan. Deskripsikan diri Anda dengan jujur dibandingkan orang lain yang Anda kenal dengan jenis kelamin dan usia yang kurang lebih sama. Jawaban Anda dijaga kerahasiaannya. Untuk setiap pernyataan, pilih 1 = Sangat tidak sesuai … 5 = Sangat sesuai.', updated_at = now() WHERE id = 6 AND code = 'bigfive';

COMMIT;
